import{_ as a,o as t,c as i,ag as o}from"./chunks/framework.BYYsWsaA.js";const h=JSON.parse('{"title":"Viewing Images","description":"","frontmatter":{},"headers":[],"relativePath":"pdf/viewing-images.md","filePath":"pdf/viewing-images.md"}'),n={name:"pdf/viewing-images.md"};function s(r,e,l,d,p,m){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="viewing-images" tabindex="-1">Viewing Images <a class="header-anchor" href="#viewing-images" aria-label="Permalink to &quot;Viewing Images&quot;">​</a></h1><p>Wafflebase stores and displays <strong>image files</strong> alongside your sheets, docs, slides, notes, and PDFs. Like a PDF, an image is a <em>view-only</em> document type — you upload the original file and view it in the browser; the image itself is never edited.</p><p>Supported formats are <strong>PNG, JPEG, GIF, and WebP</strong>, up to <strong>25 MB</strong> per file.</p><h2 id="upload-an-image" tabindex="-1">Upload an image <a class="header-anchor" href="#upload-an-image" aria-label="Permalink to &quot;Upload an image&quot;">​</a></h2><ol><li>Open your workspace</li><li>Click the <strong>New</strong> dropdown button</li><li>Select <strong>Upload Image</strong></li><li>Choose an image file from your computer</li></ol><p>The file uploads and opens in the viewer. It appears in your workspace document list with a thumbnail, and its title defaults to the file name (which you can rename).</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>You can also <strong>drag files straight onto the documents list</strong> to upload several at once — images, PDFs, spreadsheets, documents, and presentations are each routed to the matching document type, and a panel in the bottom-right shows per-file progress.</p></div><h2 id="view-an-image" tabindex="-1">View an image <a class="header-anchor" href="#view-an-image" aria-label="Permalink to &quot;View an image&quot;">​</a></h2><p>The viewer centers the image and fits it to your window. A toolbar lets you:</p><ul><li><strong>Zoom in / out</strong> — step the zoom level up or down</li><li><strong>Previous / Next</strong> — jump to the previous or next image in the same workspace without returning to the list</li><li><strong>Download</strong> — save the original file back to your computer</li></ul><p>A progress bar shows while the file downloads on first open.</p><h2 id="rename-an-image" tabindex="-1">Rename an image <a class="header-anchor" href="#rename-an-image" aria-label="Permalink to &quot;Rename an image&quot;">​</a></h2><p>Click the title in the header to rename the document. The change is reflected in your workspace list right away.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Images are read-only. To change one, edit it elsewhere and upload the new version.</p></div>',14)])])}const c=a(n,[["render",s]]);export{h as __pageData,c as default};
